function view_article(array $db,array $a): void {
    $cat=category_for($db,(int)$a['category_id']); [$body,$toc]=article_blocks($a['body']);
    $related=array_values(array_filter(published($db,$a['category_id']),fn($x)=>$x['id']!==$a['id']));$related=array_slice($related,0,3);
    $voter=hash_hmac('sha256',session_id(),csrf());$myVote=$db['votes'][$a['id'].':'.$voter]??null;
    $up=0;$down=0;foreach($db['votes'] as $key=>$value){if(str_starts_with((string)$key,$a['id'].':')){$value==='yes'?$up++:$down++;}}
    ob_start();?><div class="container article-page"><?=crumbs([['Главная','/'],[$cat['name'],category_path($cat)],[$a['title'],null]])?><div class="article-grid"><aside class="article-nav"><a class="back-category" href="<?=e(category_path($cat))?>">‹ <?=e($cat['name'])?></a><div class="toc-sidebar"><span class="sidebar-label">В ЭТОЙ СТАТЬЕ</span><?php foreach($toc as $t):?><a href="#<?=e($t['id'])?>" class="toc-link <?=($t['level']>2)?'toc-deep':''?>"><?=e($t['name'])?></a><?php endforeach;?></div><a class="other-cats" href="/#categories"><?=icon('grid',16)?> Все категории</a></aside><article class="article-main"><div class="article-label"><?=icon('file',17)?> БАЗА ЗНАНИЙ <span>•</span> <?=e($cat['name'])?></div><h1><?=e($a['title'])?></h1><p class="article-summary"><?=e($a['excerpt'])?></p><div class="article-meta"><?=icon('clock',16)?> Обновлено <?=e(to_date($a['updated_at']))?><span class="meta-dot">·</span> VOSTERA TEAM</div><div class="article-content"><?=$body?></div>
<div class="article-feedback" data-vote-area><div><strong>Статья была полезной?</strong><p>Ваш отзыв помогает улучшать базу знаний.</p></div><form method="post" action="/vote" class="vote-actions"><?=csrf_field()?><input type="hidden" name="article" value="<?=$a['id']?>"><button type="submit" name="vote" value="yes" class="vote-button <?=$myVote==='yes'?'selected':''?>">👍 Да <span><?=$up?></span></button><button type="submit" name="vote" value="no" class="vote-button <?=$myVote==='no'?'selected':''?>">👎 Нет <span><?=$down?></span></button></form></div><div class="article-actionbar"><button type="button" data-copy-link class="copy-link"><?=icon('copy',15)?> Скопировать ссылку</button><a href="/article/support-contact">Сообщить о неточности <?=icon('arrow',15)?></a></div><?php if($related):?><section class="related"><h2>Читайте также</h2><?php foreach($related as $r)echo article_row($r,$db);?></section><?php endif;?></article><aside class="article-right"><div class="article-right-card"><span class="sidebar-label">ЕСТЬ ВОПРОСЫ?</span><span class="help-circle"><?=icon('messages',26)?></span><h3>Поможем разобраться</h3><p>Обратитесь к команде через официальные каналы проекта.</p><a href="/article/support-contact" class="mini-primary">Открыть контакты <?=icon('arrow',16)?></a></div><div class="article-disclaimer"><span>i</span> Инструкции обновляются. При расхождении с официальным объявлением руководствуйтесь им.</div></aside></div></div><?php $html=ob_get_clean();render_layout($db,$a['title'],$html,'categories',$a['excerpt']);
}
