    $results=$q!==''?search_articles($db,$q):[];
    ob_start();?><div class="container inner-page search-page"><?=crumbs([['Главная','/'],['Поиск',null]])?><div class="search-heading"><span class="section-eyebrow">ПОИСК ПО БАЗЕ ЗНАНИЙ</span><h1>Найдём <span>ответ</span> вместе</h1><p>Введите вопрос, ошибку или название нужной инструкции.</p><form method="get" action="/search" class="search-full" role="search"><?=icon('search',24)?><input name="q" value="<?=e($q)?>" placeholder="Например: не могу войти в аккаунт" maxlength="100" type="search" autofocus><button type="submit">Искать <?=icon('arrow',17)?></button></form></div>
<?php if($q!==''):?><div class="inner-card results-card"><div class="inner-card-heading"><h2>Результаты по запросу «<?=e($q)?>»</h2><span><?=count($results)?> найдено</span></div><?php if($results):foreach($results as $a)echo article_row($a,$db);else:?><div class="empty-state"><span><?=icon('search',37)?></span><h3>Ничего не найдено</h3><p>Попробуйте другие слова или перейдите к разделам Wiki.</p><a class="btn btn-primary" href="/#categories">Все разделы <?=icon('arrow',16)?></a></div><?php endif;?></div><?php else:?><div class="search-suggestions"><h2>Популярные вопросы</h2><div><?php foreach([['Как начать играть','how-to-start'],['RP-термины','rp-terms'],['Не удаётся подключиться','cannot-connect'],['Забыл пароль','forgot-password'],['Написать в поддержку','support-contact']] as [$text,$s]):?><a href="/article/<?=e($s)?>"><?=icon('search',16)?> <?=e($text)?></a><?php endforeach;?></div></div><?php endif;?></div><?php $html=ob_get_clean();render_layout($db,'Поиск',$html,'search');
}
function view_login(array $db): void {
    ob_start();?><div class="container auth-page"><div class="auth-visual"><img src="/assets/img/cover.jpg" alt=""><div><span class="section-eyebrow">VOSTERA WIKI</span><h1>Управляй<br><span>знаниями.</span></h1><p>Закрытый вход для администраторов и редакторов базы знаний проекта.</p></div></div><div class="auth-form"><a href="/" class="auth-back">← Вернуться к Wiki</a><span class="section-eyebrow">ПАНЕЛЬ УПРАВЛЕНИЯ</span><h2>Вход в систему</h2><p>Введите данные вашей учётной записи.</p><form method="post" action="/login"><?=csrf_field()?><label>Логин<input required type="text" name="login" maxlength="40" minlength="3" autocomplete="username" placeholder="Ваш логин"></label><label>Пароль<input required type="password" name="password" autocomplete="current-password" placeholder="••••••••"></label><button class="btn btn-primary" type="submit">Войти в Wiki <?=icon('arrow',17)?></button></form><?php if(!$db['installed']):?><p class="auth-setup">База знаний ещё не настроена. <a href="/install">Создать администратора</a></p><?php endif;?></div></div><?php $html=ob_get_clean();render_layout($db,'Вход',$html); }
function view_install(array $db): void {
    ob_start();?><div class="container install-page"><div class="install-panel"><img class="install-brand" src="/assets/img/mark.png" width="88" height="88" alt=""><span class="section-eyebrow">ПЕРВЫЙ ЗАПУСК VOSTERA WIKI</span><h1>Установка базы знаний</h1><p>Введите установочный ключ из файла <code>INSTALL.txt</code> и создайте владельца Wiki. После создания администратора мастер установки отключится.</p><form method="post" action="/install"><?=csrf_field()?><label>Установочный ключ<input type="password" name="key" required autocomplete="off" placeholder="Ключ из INSTALL.txt"></label><label>Логин владельца<input type="text" name="login" required minlength="3" maxlength="40" pattern="[A-Za-z0-9_]{3,40}" placeholder="admin"></label><label>Пароль владельца (от 12 символов)<input type="password" name="password" required minlength="12" autocomplete="new-password" placeholder="Надёжный пароль"></label><label>Повторите пароль<input type="password" name="password_repeat" required minlength="12" autocomplete="new-password"></label><button type="submit" class="btn btn-primary">Завершить установку <?=icon('check',17)?></button></form></div></div><?php $html=ob_get_clean();render_layout($db,'Установка Wiki',$html); }
function view_error(array $db,int $status,string $text): void {
    http_response_code($status);ob_start();?><div class="container error-page"><span><?=$status?></span><h1><?=e($text)?></h1><p>Вы можете вернуться на главную или воспользоваться поиском по базе знаний.</p><a class="btn btn-primary" href="/">На главную <?=icon('arrow',17)?></a></div><?php render_layout($db,"Ошибка $status",ob_get_clean()); }
